/bin/bash -c "python - <<'PY'
import numpy as np
z=np.load('source_pixels.npz')['rgb'].astype(float)
# fit trajectory y center using midpoint from diff bbox for all frames; output peaks
from scipy import ndimage
Y,X=np.indices((144,256)); vals=[]
for f in range(96):
 d=np.abs(z[f]-np.median(z,0)).max(2)
 m=(d>8)&(X>105)&(X<180)&(Y<112)&~((X>=145)&(X<=159)&(Y>=69)&(Y<=80))
 lab,n=ndimage.label(m); best=None
 for i in range(1,n+1):
  ys,xs=np.where(lab==i)
  if len(xs)>40 and (best is None or len(xs)>best[0]): best=(len(xs),xs.min(),ys.min(),xs.max(),ys.max())
 if best:
  _,x0,y0,x1,y1=best; vals.append((f,(y0+y1)/2,(x0+x1)/2,y0,y1))
print('local minima/maxima y')
for i in range(1,len(vals)-1):
 if (vals[i][1]-vals[i-1][1])*(vals[i+1][1]-vals[i][1])<0: print(vals[i])
print('all')
for v in vals: print('%d %.1f %.1f %d %d'%v)
PY"
